// ── Platform invoices UI ─────────────────────────────────────────────────────
(function () {
  'use strict';
  function monthDefault() {
    var d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - 1);
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
  }
  function msg(t, ok) {
    var el = document.getElementById('pi-msg');
    if (el) el.innerHTML = '<span style="color:' + (ok ? 'var(--tx-ok,#059669)' : 'var(--tx-err,#b91c1c)') + '">' + t + '</span>';
  }
  function channelGuess(name) {
    var n = String(name || '').toLowerCase();
    if (n.indexOf('airbnb') >= 0) return 'airbnb';
    if (n.indexOf('booking') >= 0 || n.indexOf('bdc') >= 0) return 'booking';
    return prompt('Channel for this file? Type airbnb or booking', 'airbnb') || 'airbnb';
  }
  function renderList(scope, items) {
    var el = document.getElementById(scope === 'leased' ? 'pi-leased-list' : 'pi-b2b-list');
    if (!el) return;
    var mine = items.filter(function (x) { return x.scope === scope; });
    if (!mine.length) { el.innerHTML = '<span style="color:var(--tx3)">No files yet</span>'; return; }
    el.innerHTML = mine.map(function (x) {
      return '<div style="display:flex;justify-content:space-between;gap:8px;padding:4px 0;border-bottom:1px solid var(--bdr)">' +
        '<span>' + (x.channel || '') + ' · ' + (x.filename || '') + (x.partner ? (' · ' + x.partner) : '') + '</span>' +
        '<button class="btn sm" onclick="piDelete(\'' + x.id + '\')">Remove</button></div>';
    }).join('');
  }
  window.piReload = async function () {
    var inp = document.getElementById('pi-month');
    if (inp && !inp.value) inp.value = monthDefault();
    var month = (inp && inp.value) || monthDefault();
    try {
      var st = await fetch('/api/platform-invoices/status').then(function (r) { return r.json(); });
      var s = document.getElementById('pi-status');
      if (s) s.textContent = 'Accountant email: ' + (st.accountantEmail || '(set PLATFORM_INVOICE_ACCOUNTANT_EMAIL)') +
        ' · Airbnb portal: ' + (st.airbnbConfigured ? 'credentials set' : 'not set') +
        ' · Booking portal: ' + (st.bookingConfigured ? 'credentials set' : 'not set');
      var j = await fetch('/api/platform-invoices?month=' + encodeURIComponent(month)).then(function (r) { return r.json(); });
      if (!j.ok) throw new Error(j.error || 'load failed');
      renderList('leased', j.items || []);
      renderList('b2b', j.items || []);
    } catch (e) { msg(e.message || String(e), false); }
  };
  window.piUpload = function (input, scope) {
    var file = input.files && input.files[0];
    input.value = '';
    if (!file) return;
    var month = (document.getElementById('pi-month') || {}).value || monthDefault();
    var partner = scope === 'b2b' ? ((document.getElementById('pi-partner') || {}).value || '').trim() : '';
    var channel = channelGuess(file.name);
    var reader = new FileReader();
    reader.onload = async function () {
      try {
        var dataB64 = String(reader.result || '').split(',')[1] || '';
        var r = await fetch('/api/platform-invoices', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            month: month, channel: channel, scope: scope, partner: partner,
            name: file.name, mime: file.type || 'application/pdf', size: file.size,
            dataB64: dataB64, by: (window._ACC && window._ACC.user) || localStorage.getItem('elysian_user_name') || ''
          })
        }).then(function (x) { return x.json(); });
        if (!r.ok) throw new Error(r.error || 'upload failed');
        msg('Uploaded ' + file.name, true);
        piReload();
      } catch (e) { msg(e.message || String(e), false); }
    };
    reader.readAsDataURL(file);
  };
  window.piDelete = async function (id) {
    try {
      var r = await fetch('/api/platform-invoices/' + id, { method: 'DELETE' }).then(function (x) { return x.json(); });
      if (!r.ok) throw new Error(r.error || 'delete failed');
      piReload();
    } catch (e) { msg(e.message || String(e), false); }
  };
  window.piSend = async function (scope) {
    var month = (document.getElementById('pi-month') || {}).value || monthDefault();
    var partner = scope === 'b2b' ? ((document.getElementById('pi-partner') || {}).value || '').trim() : '';
    var to = '';
    if (scope === 'b2b') to = prompt('Partner email for this pack:', '') || '';
    try {
      var r = await fetch('/api/platform-invoices/send', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ month: month, scope: scope, partner: partner, to: to })
      }).then(function (x) { return x.json(); });
      if (!r.ok) throw new Error(r.error || 'send failed');
      msg('Sent ' + r.count + ' file(s) to ' + (r.to || []).join(', '), true);
    } catch (e) { msg(e.message || String(e), false); }
  };
  function piYmFromTs(t) {
    if (t == null || t === '') return '';
    var n = Number(t);
    if (!isFinite(n)) { var s = String(t); return s.length >= 7 ? s.slice(0, 7) : ''; }
    if (n < 1e12) n *= 1000;
    var d = new Date(n);
    if (isNaN(d.getTime())) return '';
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
  }
  function piPrevMonth(ym) {
    var p = String(ym || '').split('-');
    var y = parseInt(p[0], 10), m = parseInt(p[1], 10);
    if (!y || !m) return '';
    var d = new Date(y, m - 2, 1);
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
  }
  function piChan(b) {
    var s = String((b && (b.platform || b.channel)) || '').toLowerCase();
    if (s.indexOf('air') >= 0) return 'airbnb';
    if (s.indexOf('book') >= 0) return 'booking';
    return 'other';
  }
  window.piHealth = function () {
    var month = (document.getElementById('pi-month') || {}).value || monthDefault();
    var box = document.getElementById('pi-health');
    if (!box) return;
    box.style.display = 'block';
    var bks = (typeof S !== 'undefined' && Array.isArray(S.bks)) ? S.bks : [];
    if (!bks.length) { box.innerHTML = '<b>Hosthub health check</b> — no bookings loaded. Sync Hosthub first.'; return; }
    var airInv = 0, airCredit = 0, bdcExpect = 0;
    var bdcBookMonth = piPrevMonth(month);
    bks.forEach(function (b) {
      var ch = piChan(b);
      var createdYm = piYmFromTs(b.createdOnChannel != null ? b.createdOnChannel : b.created);
      var cancelYm = piYmFromTs(b.cancelledAt);
      if (ch === 'airbnb' && createdYm === month) airInv++;
      if (ch === 'airbnb' && b.cancelled && cancelYm === month) airCredit++;
      if (ch === 'booking' && createdYm === bdcBookMonth && !b.cancelled) bdcExpect++;
    });
    box.innerHTML =
      '<div style="font-weight:600;margin-bottom:6px">Hosthub health check for document month <code>' + month + '</code></div>' +
      '<div><b>Airbnb VAT invoices</b> — created in ' + month + ': <b>' + airInv + '</b></div>' +
      '<div style="margin-top:4px"><b>Airbnb credit notes</b> — cancelledAt in ' + month + ': <b>' + airCredit + '</b></div>' +
      '<div style="margin-top:4px"><b>Booking.com</b> (admin.booking.com) — invoice <code>' + month + '</code> covers bookings in <code>' + bdcBookMonth + '</code>: <b>' + bdcExpect + '</b></div>' +
      '<div style="margin-top:8px;color:var(--tx3);font-size:11.5px">Confirm≠cancel months → invoice in one month and credit note in the other.</div>';
    fetch('/api/platform-invoices?month=' + encodeURIComponent(month)).then(function (r) { return r.json(); }).then(function (j) {
      if (!j || !j.ok) return;
      var items = j.items || [];
      var aUp = items.filter(function (x) { return x.channel === 'airbnb'; }).length;
      var bUp = items.filter(function (x) { return x.channel === 'booking'; }).length;
      box.innerHTML += '<div style="margin-top:8px">In vault this month: Airbnb <b>' + aUp + '</b> · Booking.com <b>' + bUp + '</b></div>';
    }).catch(function () {});
  };
  window.piPull = async function () {
    var month = (document.getElementById('pi-month') || {}).value || monthDefault();
    msg('Pulling from portals (Airbnb + admin.booking.com — can take a few minutes)…', true);
    try {
      var res = await fetch('/api/platform-invoices/pull', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ month: month, channel: 'all' })
      });
      var r = await res.json();
      if (!res.ok) throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (r.errors && r.errors.length ? (' · ' + JSON.stringify(r.errors).slice(0, 240)) : ''));
      var n = (r.saved || []).length;
      msg('Pulled ' + n + ' PDF(s)' + (r.errors && r.errors.length ? (' · warnings: ' + r.errors.length) : ''), n > 0);
      piReload();
      try { piHealth(); } catch (e2) {}
    } catch (e) { msg(e.message || String(e), false); }
  };
  document.addEventListener('DOMContentLoaded', function () {
    var inp = document.getElementById('pi-month');
    if (inp && !inp.value) inp.value = monthDefault();
  });
  var _piNav = window.navDdGo;
  if (typeof _piNav === 'function') {
    window.navDdGo = function (t) {
      _piNav(t);
      if (t === 'platinv') try { piReload(); } catch (e) {}
    };
  }
})();

