  }
  function piPrevMonth(ym) {
    var p = String(ym || '').split('-');
    var y = parseInt(p[0], 10), m = parseInt(p[1], 10);
    if (!y || !m) return '';
    var d = new Date(y, m - 2, 1);
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
  }
  function piChan(b) {
    var s = String((b && (b.platform || b.channel)) || '').toLowerCase();
    if (s.indexOf('air') >= 0) return 'airbnb';
    if (s.indexOf('book') >= 0) return 'booking';
    return 'other';
  }
  function renderSteps() {
    var labels = ['Start', 'Expect', 'Collect', 'Review', 'Ship'];
    var box = document.getElementById('pi-steps');
    if (!box) return;
    box.innerHTML = labels.map(function (lab, i) {
      var n = i + 1;
      var on = PI.step === n;
      var done = PI.step > n;
      return '<button type="button" class="btn sm" onclick="piGo(' + n + ')" style="' +
        (on ? 'background:var(--gold,#C9A84C);color:#111;border-color:transparent;font-weight:650' :
          done ? 'opacity:.9' : 'opacity:.65') + '">' + n + ' · ' + lab + '</button>';
    }).join('');
    for (var s = 1; s <= 5; s++) {
      var p = document.getElementById('pi-panel-' + s);
      if (p) p.style.display = (s === PI.step) ? 'block' : 'none';
    }
  }
  function renderList(elId, items) {
    var el = document.getElementById(elId);
    if (!el) return;
    if (!items.length) { el.innerHTML = '<span style="color:var(--tx3)">No files yet</span>'; return; }
