    var a = items.filter(function (x) { return x.channel === 'airbnb' && x.partner !== 'credit_note' && !/credit/i.test(x.filename || ''); }).length;
    var c = items.filter(function (x) { return x.channel === 'airbnb' && (x.partner === 'credit_note' || /credit/i.test(x.filename || '')); }).length;
    var b = items.filter(function (x) { return x.channel === 'booking'; }).length;
    var el = document.getElementById('pi-collect-summary');
    if (!el) return;
