      '<div>Vault vs expect — Airbnb invoices <b>' + a + '</b>/' + (h.airInv || 0) +
      ' · credit notes <b>' + c + '</b>/' + (h.airCredit || 0) +
      ' · Booking.com <b>' + b + '</b> file(s) (expect ~' + (h.bdcExpect || 0) + ' bookings covered)</div>';
  }
  function reviewHtml() {
    var h = PI.health || {};
    var leased = (PI.items || []).filter(function (x) { return x.scope === 'leased'; });
    var b2b = (PI.items || []).filter(function (x) { return x.scope === 'b2b'; });
    var el = document.getElementById('pi-review');
    if (!el) return;
    el.innerHTML =
      '<div><b>Month</b> <code>' + monthVal() + '</code></div>' +
      '<div style="margin-top:6px"><b>Elysian pack</b>: ' + leased.length + ' PDF(s)</div>' +
      '<div style="margin-top:4px;color:var(--tx3)">Hosthub expect — Airbnb inv ' + (h.airInv || 0) +
      ', credit notes ' + (h.airCredit || 0) + ', Booking bookings in prior month ' + (h.bdcExpect || 0) + '</div>' +
      (b2b.length ? ('<div style="margin-top:6px"><b>Other groups</b>: ' + b2b.length + ' PDF(s)</div>') : '') +
