    renderSteps();
    if (PI.step === 2) piHealth();
    if (PI.step === 3) piReload();
    if (PI.step === 4) piReload().then(reviewHtml);
    if (PI.step === 5) {
      var st = PI.status || {};
      var el = document.getElementById('pi-ship-to');
      if (el) el.innerHTML = 'To: <b>' + (st.accountantEmail || 'info@e-newgeneration.gr, info@elysianproperties.eu') + '</b>';
    }
  };
  window.piOnMonthChange = function () {
    PI.health = null;
    try { localStorage.setItem('pi_month', monthVal()); } catch (e) {}
    if (PI.step >= 2) piHealth();
    piReload();
  };
  window.piPipelineStart = function () {
    var inp = document.getElementById('pi-month');
    if (inp && !inp.value) inp.value = monthDefault();
    msg('Running Hosthub expect…', true);
    Promise.resolve(piHealth()).then(function () { piGo(2); msg('', true); });
  };
  window.piHealth = function () {
    var month = monthVal();
    var box = document.getElementById('pi-health');
    if (!box) return Promise.resolve();
    var bks = (typeof S !== 'undefined' && Array.isArray(S.bks)) ? S.bks : [];
    if (!bks.length) {
      box.innerHTML = '<b>Hosthub</b> — no bookings loaded. Sync Hosthub on the Dashboard first, then refresh expect.';
      PI.health = { airInv: 0, airCredit: 0, bdcExpect: 0 };
      return Promise.resolve();
    }
    var airInv = 0, airCredit = 0, bdcExpect = 0;
    var bdcBookMonth = piPrevMonth(month);
    bks.forEach(function (b) {
      var ch = piChan(b);
      var createdYm = piYmFromTs(b.createdOnChannel != null ? b.createdOnChannel : b.created);
      var cancelYm = piYmFromTs(b.cancelledAt);
      if (ch === 'airbnb' && createdYm === month) airInv++;
      if (ch === 'airbnb' && b.cancelled && cancelYm === month) airCredit++;
      if (ch === 'booking' && createdYm === bdcBookMonth && !b.cancelled) bdcExpect++;
    });
    PI.health = { airInv: airInv, airCredit: airCredit, bdcExpect: bdcExpect, bdcBookMonth: bdcBookMonth };
    box.innerHTML =
      '<div>Document month <code>' + month + '</code></div>' +
      '<div style="margin-top:6px"><b>Airbnb VAT invoices</b> (created): <b>' + airInv + '</b></div>' +
      '<div style="margin-top:4px"><b>Airbnb credit notes</b> (cancelledAt): <b>' + airCredit + '</b></div>' +
      '<div style="margin-top:4px"><b>Booking.com</b> invoice covers bookings in <code>' + bdcBookMonth + '</code>: <b>' + bdcExpect + '</b> active</div>' +
      '<div style="margin-top:8px;color:var(--tx3);font-size:11.5px">Confirm≠cancel months → invoice in one month and credit note in the other.</div>';
    return fetch('/api/platform-invoices?month=' + encodeURIComponent(month)).then(function (r) { return r.json(); }).then(function (j) {
      if (!j || !j.ok) return;
      var items = j.items || [];
      box.innerHTML += '<div style="margin-top:8px">Already in vault: <b>' + items.length + '</b> file(s)</div>';
    }).catch(function () {});
  };
  window.piReload = async function () {
    var month = monthVal();
    try {
      var st = await fetch('/api/platform-invoices/status').then(function (r) { return r.json(); });
      PI.status = st;
      var sEl = document.getElementById('pi-status');
