      renderList('pi-b2b-list', PI.items.filter(function (x) { return x.scope === 'b2b'; }));
      collectSummary();
      if (PI.step === 4) reviewHtml();
    } catch (e) { msg(e.message || String(e), false); }
    return PI.items;
  };
  window.piUploadMany = function (input, scope) {
    var files = input.files ? Array.prototype.slice.call(input.files) : [];
