                dataB64: dataB64, source: 'upload'
              })
            }).then(function (r) { return r.json(); }).then(function (j) {
              if (!j || !j.ok) reject(new Error((j && j.error) || 'upload failed'));
              else resolve();
            }).catch(reject);
          };
          reader.onerror = reject;
          reader.readAsDataURL(file);
        });
      });
    });
    chain.then(function () { msg('Uploaded ' + files.length + ' file(s)', true); return piReload(); })
      .catch(function (e) { msg(e.message || String(e), false); });
  };
  window.piUpload = function (input, scope) { piUploadMany(input, scope); };
  window.piDelete = async function (id) {
    if (!id || !confirm('Delete this file from the vault?')) return;
