      var n = (r.saved || []).length;
      msg('Pulled ' + n + ' PDF(s)' + (r.errors && r.errors.length ? (' · warnings: ' + r.errors.length) : '') + (n ? '' : ' — use Upload if portals blocked login'), n > 0);
      await piReload();
    } catch (e) { msg(e.message || String(e), false); }
  };
  window.piSend = async function (scope) {
    var month = monthVal();
    var partner = scope === 'b2b' ? ((document.getElementById('pi-partner') || {}).value || '').trim() : '';
