    if (scope === 'b2b') to = prompt('Partner email for this pack:', '') || '';
    try {
      var r = await fetch('/api/platform-invoices/send', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ month: month, scope: scope, partner: partner, to: to, subject: (scope==='leased' ? ('PLATFORM INVOICES ' + month) : undefined), text: (scope==='leased' ? ('Finished Elysian platform-invoice pack for ' + month + ' (ενδοκοινοτικά / Airbnb+Booking).\n') : undefined) })
      }).then(function (x) { return x.json(); });
      if (!r.ok) throw new Error(r.error || 'send failed');
      msg('Sent ' + r.count + ' file(s) to ' + (r.to || []).join(', '), true);
      return r;
    } catch (e) { msg(e.message || String(e), false); throw e; }
  };
  window.piShip = async function () {
    var btn = document.getElementById('pi-ship-btn');
    var out = document.getElementById('pi-ship-result');
    if (btn) btn.disabled = true;
    msg('Shipping finished pack…', true);
    try {
      var r = await piSend('leased');
      if (out) {
        out.innerHTML =
          '<div style="color:var(--tx-ok,#059669);font-weight:650">Finished product shipped</div>' +
          '<div style="margin-top:6px">Month <code>' + monthVal() + '</code> · ' + (r.count || 0) + ' PDF(s)</div>' +
          '<div style="margin-top:4px">To: ' + (r.to || []).join(', ') + '</div>' +
          '<div style="margin-top:10px;color:var(--tx3)">Elysian platform invoices pack is with the accountants. Optional: email other-group packs above.</div>';
      }
      msg('Shipped', true);
    } catch (e) {
      if (out) out.innerHTML = '<span style="color:var(--tx-err,#b91c1c)">' + (e.message || e) + '</span>';
    } finally {
      if (btn) btn.disabled = false;
    }
  };

  function boot() {
    var inp = document.getElementById('pi-month');
    if (inp) {
      try { inp.value = localStorage.getItem('pi_month') || monthDefault(); } catch (e) { inp.value = monthDefault(); }
    }
    var step = 1;
    try { step = parseInt(localStorage.getItem('pi_step_' + monthVal()) || '1', 10) || 1; } catch (e) {}
    PI.step = step;
    renderSteps();
    piReload();
  }
  document.addEventListener('DOMContentLoaded', boot);
  var _piShow = window.showTab;
  if (typeof _piShow === 'function') {
    window.showTab = function (t, el) {
      _piShow(t, el);
      if (t === 'platinv') { try { boot(); } catch (e) {} }
    };
  }
  var _piNav = window.navDdGo;
  if (typeof _piNav === 'function') {
    window.navDdGo = function (t) {
      _piNav(t);
      if (t === 'platinv') try { boot(); } catch (e) {}
    };
  }
})();
